package com.hospital.system.repository; import com.hospital.system.model.Patient; import java.sql.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.core.RowMapper; import org.springframework.stereotype.Repository; @Repository public class PatientRepository { private final JdbcTemplate db; public PatientRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Patient> map=(r,n)->{Patient p=new Patient();p.patientId=r.getLong("patient_id");p.fullName=r.getString("full_name");p.dateOfBirth=r.getObject("date_of_birth",java.time.LocalDate.class);p.gender=r.getString("gender");p.phone=r.getString("phone");p.email=r.getString("email");p.address=r.getString("address");p.createdAt=r.getTimestamp("created_at").toLocalDateTime();return p;}; public List<Patient> all(String q){String x=q==null?"":q;return db.query("SELECT * FROM patient WHERE full_name LIKE ? OR phone LIKE ? ORDER BY patient_id DESC",map,"%"+x+"%","%"+x+"%");} public Optional<Patient> one(Long id){return db.query("SELECT * FROM patient WHERE patient_id=?",map,id).stream().findFirst();} public int add(Patient p){return db.update("INSERT INTO patient(full_name,date_of_birth,gender,phone,email,address) VALUES(?,?,?,?,?,?)",p.fullName,p.dateOfBirth,p.gender,p.phone,p.email,p.address);} public int update(Long id,Patient p){return db.update("UPDATE patient SET full_name=?,date_of_birth=?,gender=?,phone=?,email=?,address=? WHERE patient_id=?",p.fullName,p.dateOfBirth,p.gender,p.phone,p.email,p.address,id);} public int delete(Long id){return db.update("DELETE FROM patient WHERE patient_id=?",id);} }
